	/**
	 * Default Constructor
	 */
    public InsuredObjectService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new InsuredObjectEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(InsuredObjectRepository.class) );
		this.validator		= applicationContext.getBean(InsuredObjectValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		InsuredObject
	 */
		public InsuredObject createInsuredObject( CreateInsuredObjectCommand command ) {

		InsuredObject entity = new InsuredObject();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setInsuredObjectId( command.getInsuredObjectId() );
            entity.setDescription( command.getDescription() );
            entity.setSerialOrId( command.getSerialOrId() );
            entity.setPrimaryAddress( command.getPrimaryAddress() );
            entity.setObjectType( command.getObjectType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of InsuredObject {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateInsuredObjectCommand
	 * @return		InsuredObject
	 */
	public InsuredObject updateInsuredObject( UpdateInsuredObjectCommand command ) {

		InsuredObject entity = new InsuredObject();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setInsuredObjectId( command.getInsuredObjectId() );
            entity.setDescription( command.getDescription() );
            entity.setSerialOrId( command.getSerialOrId() );
            entity.setPrimaryAddress( command.getPrimaryAddress() );
            entity.setPolicy( command.getPolicy() );
            entity.setCoverages( command.getCoverages() );
            entity.setObjectType( command.getObjectType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of InsuredObject {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteInsuredObjectCommand
	 */
	public void delete( DeleteInsuredObjectCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getInsuredObjectId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of InsuredObject {0} ", id );

	}

	/**
	 * Method to retrieve the InsuredObject via InsuredObjectFetchOneSummary
	 * @param 	summary InsuredObjectFetchOneSummary
	 * @return 	InsuredObjectFetchOneResponse
	 */
	public InsuredObject getInsuredObject( InsuredObjectFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "InsuredObjectFetchOneSummary arg cannot be null" );

		InsuredObject entity = null;
		UUID id = summary.getInsuredObjectId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a InsuredObject using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all InsuredObjects
	 *
	 * @return 	List<InsuredObject>
	 */
    public List<InsuredObject> getAllInsuredObject() {
		List<InsuredObject> list = projector.findAll( new FindAllInsuredObjectQuery() );
		return list;
	}

	/**
	 * assign Policy on InsuredObject
	 * @param		command AssignPolicyToInsuredObjectCommand
	 */
	public void assignPolicy( AssignPolicyToInsuredObjectCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPolicy(command.getInsuredObjectId(), command.getAssignment());

	}

	/**
	 * unAssign Policy on InsuredObject
	 * @param		command UnAssignPolicyFromInsuredObjectCommand
	 */
	public void unAssignPolicy( UnAssignPolicyFromInsuredObjectCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignPolicy(command.getInsuredObjectId());
	}
	

	/**
	 * add PolicyCoverage to Coverages
	 * @param		command AssignCoveragesToInsuredObjectCommand
	 */
	public void addToCoverages( AssignCoveragesToInsuredObjectCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToCoverages(command.getInsuredObjectId(), command.getAddTo());
	}

	/**
	 * remove PolicyCoverage from Coverages
	 * @param		command RemoveCoveragesFromInsuredObjectCommand
	 */
	public void removeFromCoverages( RemoveCoveragesFromInsuredObjectCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromCoverages(command.getInsuredObjectId(), command.getRemoveFrom());
	}




